    public function createSimulation(array $data): array
    {
        return DB::transaction(function () use ($data): array {
            $namespace = 'finance.simulation.create'; if ($replay = $this->begin($namespace, $data)) return $replay; $this->unique('finance_simulations', 'simulation_number', $data['simulation_number'], $data); [$lines, $debit, $credit] = $this->lines($data['lines'], $data, false); $id = (string) Str::uuid(); $now = CarbonImmutable::now();
            DB::table('finance_simulations')->insert(['id' => $id, 'company_id' => $data['company_id'], 'plant_id' => $data['plant_id'], 'simulation_number' => $data['simulation_number'], 'name' => trim($data['name']), 'description' => $this->nullable($data['description'] ?? null), 'as_of_date' => $data['as_of_date'], 'status' => 'DRAFT', 'total_debit' => $debit, 'total_credit' => $credit, 'projected_profit' => 0, 'result_json' => null, 'record_version' => 1, 'created_by' => $data['actor_id'], 'run_at' => null, 'run_by' => null, 'created_at' => $now, 'updated_at' => $now]); $this->insertLines('finance_simulation_lines', 'finance_simulation_id', $id, $lines, $data, $now, true);
            $result = $this->result('finance_simulation', $id, 'DRAFT', 1, ['total_debit' => $debit, 'total_credit' => $credit]); $this->record('CREATE_FINANCE_SIMULATION', 'finance.simulation.created', 'finance_simulation', $id, $data, 1, ['line_count' => count($lines), 'ledger_effect' => 'NONE'], $result); $this->complete($namespace, $data, $result); return $result;
        }, 3);
    }

    public function runSimulation(string $id, array $data): array
    {
        return DB::transaction(function () use ($id, $data): array {
            $namespace = 'finance.simulation.run.'.$id; if ($replay = $this->begin($namespace, $data + ['simulation_id' => $id])) return $replay; $simulation = $this->find('finance_simulations', $id, $data, 'Finance simulation', true); $this->version($simulation, $data, 'finance simulation'); $this->status($simulation, ['DRAFT', 'RUN'], 'Only a draft or previously run simulation can be recalculated.');
            $rows = DB::table('finance_simulation_lines as line')->join('chart_accounts as account', 'account.id', '=', 'line.account_id')->where('line.finance_simulation_id', $id)->get(['line.*', 'account.account_type', 'account.account_code']); $revenue = $expense = '0.0000'; foreach ($rows as $row) { if ($row->account_type === 'REVENUE') $revenue = bcadd($revenue, bcsub($this->decimal($row->credit_amount), $this->decimal($row->debit_amount), 4), 4); if ($row->account_type === 'EXPENSE') $expense = bcadd($expense, bcsub($this->decimal($row->debit_amount), $this->decimal($row->credit_amount), 4), 4); } $profit = bcsub($revenue, $expense, 4); $snapshot = ['ledger_isolated' => true, 'as_of_date' => (string) $simulation->as_of_date, 'revenue' => $revenue, 'expense' => $expense, 'projected_profit' => $profit, 'line_count' => $rows->count(), 'assumptions' => $rows->map(fn (object $row) => ['account_code' => $row->account_code, 'assumption' => $row->assumption])->filter(fn (array $row) => $row['assumption'] !== null)->values()->all()]; $version = (int) $simulation->record_version + 1;
            DB::table('finance_simulations')->where('id', $id)->update(['status' => 'RUN', 'projected_profit' => $profit, 'result_json' => json_encode($snapshot, JSON_THROW_ON_ERROR), 'run_at' => now(), 'run_by' => $data['actor_id'], 'record_version' => $version, 'updated_at' => now()]); $result = $this->result('finance_simulation', $id, 'RUN', $version, ['projected_profit' => $profit, 'result' => $snapshot]); $this->record('RUN_FINANCE_SIMULATION', 'finance.simulation.run', 'finance_simulation', $id, $data, $version, ['ledger_effect' => 'NONE', 'projected_profit' => $profit], $result); $this->complete($namespace, $data, $result); return $result;
        }, 3);
    }

    public function createAdjustment(array $data): array
    {
        return DB::transaction(function () use ($data): array { $namespace = 'finance.adjustment.create'; if ($replay = $this->begin($namespace, $data)) return $replay; $this->unique('finance_adjustments', 'adjustment_number', $data['adjustment_number'], $data); [$lines, $debit, $credit] = $this->lines($data['lines'], $data, true); $id = (string) Str::uuid(); $now = CarbonImmutable::now(); DB::table('finance_adjustments')->insert(['id' => $id, 'company_id' => $data['company_id'], 'plant_id' => $data['plant_id'], 'adjustment_number' => $data['adjustment_number'], 'adjustment_date' => $data['adjustment_date'], 'adjustment_type' => $data['adjustment_type'], 'reason' => trim($data['reason']), 'status' => 'DRAFT', 'total_debit' => $debit, 'total_credit' => $credit, 'journal_id' => null, 'record_version' => 1, 'created_by' => $data['actor_id'], 'submitted_at' => null, 'submitted_by' => null, 'approved_at' => null, 'approved_by' => null, 'posted_at' => null, 'posted_by' => null, 'cancelled_at' => null, 'cancelled_by' => null, 'cancellation_reason' => null, 'created_at' => $now, 'updated_at' => $now]); $this->insertLines('finance_adjustment_lines', 'finance_adjustment_id', $id, $lines, $data, $now); $result = $this->result('finance_adjustment', $id, 'DRAFT', 1, ['total_debit' => $debit]); $this->record('CREATE_FINANCE_ADJUSTMENT', 'finance.adjustment.created', 'finance_adjustment', $id, $data, 1, ['line_count' => count($lines)], $result); $this->complete($namespace, $data, $result); return $result; }, 3);
